window.DICTIONARY_ENTRY_SHARDS["0064-0073"]={"0064-0073:cbecbf5b8e1d5b":{"word":"Dschungel","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschun·gel","de-DE":"Dschun·gel"},"forms":[{"form":"Dschungel","tags":["Nominativ","Singular"]},{"form":"Dschungeln","tags":["Nominativ","Plural"]},{"form":"Dschungels","tags":["Nominativ","Plural"]}],"senses":[{"definition":"dichter tropischer oder subtropischer Sumpfwald"},{"definition":"undurchdringliches Gewirr, wirres Durcheinander; etwas (Angelegenheit, Sache, Sachverhalt), das undurchschaubar ist oder erscheint"}],"synonyms":["(wüstes / regelloses / wildes) Durcheinander","Busch","Chaos","Gewirr","grüne Hölle","Kuddelmuddel","Pelemele","Regenwald","Salat","Sammelsurium","Tohuwabohu","Tollhaus","tropischer Regenwald","Unordnung","Urwald","Verhau","Wildnis","Wirrnis","Wirrwarr","Wust"],"origins":["Der Ausdruck wurde im früheren 19. Jahrhundert aus dem gleichbedeutend englischen jungle ^(→ en) entlehnt, das seinerseits aus dem Hindi जंगल (ISO 15919: jaṅgala) ^(→ hi) m ‚Ödland; Wald; wildes Land, Wildnis‘ stammt, das über ein (erschlossenes) *jaṅgalaḥ m ‚wasserarme, menschenleere, unfruchtbare Gegend‘ auf die altindischen Formen जाङ्गलः (IAST: jāṅgalaḥ) ^(→ sa) ‚trocken, spärlich bewachsen‘ beziehungsweise जङ्गल (IAST: jaṅgala) ^(→ sa) ‚Adjektiv: trocken, wasserarm, wüstenartig; unfruchtbar; maskulines Substantiv: wüster, unbebauter Boden‘ zurückzuführen sind.","Das Wort kam im Deutschen bis Ende des 19. Jahrhunderts noch häufig in der englischen Form vor, daneben gab es zahlreiche, meist erfolglose Versuche einer aussprachegerechten Schreibung wie Djungel, Dschungle, Jangel, Dschangel, Dschengel, Dschöngel, Dschongel. Die Pluralformen Dschangeln und Dschungeln sind bereits ab 1880 im Duden lexikalisiert, die entsprechenden Singularformen ab 1915. Die Schreibung Dschangel ist im Duden ab 1941 entfallen.","Seit Anfang des 20. Jahrhunderts ist das Wort dann auch im bildlichen und übertragenen Sinne in Gebrauch."],"examples":[{"text":"Auch der Dschungel des Amazonasbeckens ist nicht undurchdringlich.","reference":""},{"text":"„Hier hauſen in den geradezu undurchdringlichen Dſchungeln die Thiere der Wildniß, ohne irgendwie von einem Menſchen behelligt zu werden.“","reference":"A. E. Brehm: Jlluſtrirtes Thierleben. Eine allgemeine Kunde des Thierreichs. 1. Auflage. Zweiter Band, Verlag des Bibliographiſchen Jnſtituts, Hildburghauſen 1865, Seite 659 (Zitiert nach Deutsches Textarchiv) ."},{"text":"„Zu dieser letzteren Tribus gehört die fast an 200 Arten zählende Gattung Calamus selbst (einschliesslich Daemonorops), die Rotang-Palmen, von welcher Nordost-Australien noch 4 Arten besitzt und die in Borneo ihr Maximum zu erreichen scheint, furchtbar durch die stacheltragenden Geisseln ihrer die verwachsenen Dschungels unwegsam machenden Blattspitzen und Kolbenzweige; ihr gehören auch die Sagopalmen (Metroxylon und Pigafetta) von Java bis zu den Fidji-Inseln an.“","reference":"Oscar Drude: HANDBUCH DER PFLANZENGEOGRAPHIE. 1. Auflage. VERLAG VON J. ENGELHORN, STUTTGART 1890, Seite 176 (Zitiert nach Deutsches Textarchiv) ."},{"text":"„In den Abgründen dieſes Meeres, […] hauſt der Wurzelhaarſtern, […] ein Tier, fremd in ſeiner Zeit, ein einſamer Nachzügler aus dem blauen Wundermeer der Kreideperiode, wo die rieſenhaften Seelilien wie ſchillernde Palmenwälder der Tiefe ſich wiegten und den ſcheußlichen Reptilien jener Tage Schlupfwinkel boten wie heute das indiſche Dſchungel dem Königstiger …..“","reference":"W. Bölsche: Das Liebesleben in der Natur. Eine Entwickelungsgeschichte der Liebe. 1. Auflage. [1. Band] 1. bis 4. Tausend, Verlegt bei Eugen Diederichs, Florenz/Leipzig 1898, Seite 17 (Zitiert nach Deutsches Textarchiv) ."},{"text":"„Aber sie fürchten ihn auch, denn Tabaqui wird leicht von Tollwut befallen, viel leichter als irgendein anderes Tier in der Dschungel.“","reference":"Rudyard Kipling: Das Dschungelbuch. In: Gesammelte Werke. [Band 1]: Dschungelwelt, Deutsche Buch-Gesellschaft, Berlin/Darmstadt/Wien 1965 . Zitiert nach Rudyard Kipling: Das Dschungelbuch. In: Projekt Gutenberg-DE. Moglis Brüder (URL, abgerufen am 30. September 2021) . Alte Version im Internet-Archiv abrufbar. *"},{"text":"„Einen Moment später hörten wir einen Entsetzensschrei, schriller als wir es von den Vögeln im Dschungel gewohnt waren.“","reference":"John Goldsmith: Die Rückkehr zur Schatzinsel. vgs verlagsgesellschaft, Köln 1987 (Originaltitel: Return to Treasure Island, übersetzt von Uta Haas), ISBN 3-8025-5046-3, Seite 99 (englische Originalausgabe 1985) ."},{"text":"„Jährlich gehen nach einer neuen Studie 18,8 Millionen Hektar Regenwald verloren. Bereits drei Viertel der Dschungel Westafrikas gelten als verbuschte Rodungsbrache.“","reference":"Weltforstkongreß beginnt in Paris: Alarm im Regenwald - Kahlschlag schreitet rasend schnell voran. In: Nürnberger Nachrichten. 17. September 1991, Seite 5 ."},{"text":"„Vom 1. Januar bis zum 5. Februar haben die Tamil Tigers ihre wichtigsten Stützpunkte im Nordosten Sri Lankas verloren: Kilinochchi, den Sitz ihrer Separatistenregierung, Elephant Pass, den strategischen Ort am Zugang zur Halbinsel Jaffna, die Hafenstädte Mullaitivu und Chalai, wo Versorgungsschiffe mit Nachschub ankamen und die bewaffneten Schnellboote der LTTE stationiert waren, die Rollbahnen im Dschungel, die für den Ausbau ihrer Luftwaffe vorgesehen waren, und die Bunker, in denen ihr Führer Vellupillai Prabhakaran die militärischen Operationen plante und lenkte.“","reference":"Eric Paul Meyer: Sieg ist keine Lösung. In: Le Monde diplomatique. Nummer 8834, 13. März 2009 (übersetzt von Edgar Peinelt aus dem Französischen), ISSN 0026-9395, Seite 4 (Deutschsprachige Ausgabe: LMd Archiv-URL, taz Archiv-URL, abgerufen am 30. September 2021) ."},{"text":"„Er startete seinen Feldzug aus dem Südosten Venezuelas, aus dem unwegsamen Dschungel am Orinoco.“","reference":"Marianne Wellershoff: Stratege der Freiheit. In: SPIEGEL GESCHICHTE. Heft 1, 2016, ISSN 1868-7318, Seite 44 (SPIEGEL GESCHICHTE Archiv-URL, abgerufen am 30. September 2021) ."},{"text":"„Die Hecken fielen Rodenbeck auf, wahre Dschungel von schnell wachsenden Rosen mit fleischigen dicht befilzten Stengeln.“","reference":"Gerd Gaiser: Die sterbende Jagd. 1. Auflage. Carl Hanser Verlag, München 1953, Seite 150 (Zitiert nach Google Books) ."},{"text":"„Was er als Wohnzimmer bezeichnet, ist ein Dschungel aus senkrechten Rundhölzern und Latten, Versprießung genannt, die Decke ist heute betoniert worden, Sacktücher drauf, es tropft.“","reference":"Max Frisch: Mein Name sei Gantenbein. 1.–15. Tausend, Suhrkamp Verlag, Frankfurt am Main 1964, Seite 401 ."},{"text":"„Die italienische Gesellschaft ist ein Dschungel, durchsetzt mit ein paar weniger unwirtlichen Lichtungen: einige Regionen im Norden sowie die ‚roten‘ Regionen Mittelitaliens. Gültigkeit haben in diesem Dschungel weder die Gesetze des Marktes noch die des Staates, sondern die des Privilegs, der Zugehörigkeit zu bestimmten Gruppen, des Ressentiments und der Angst.“","reference":"Carlo Galli: Kavaliersdelikte für alle. In: Le Monde diplomatique. Nummer 8985, 11. September 2009 (übersetzt von Rita Seuß aus dem Italienischen), ISSN 0026-9395, Seite 3 (Deutschsprachige Ausgabe: LMd Archiv-URL, taz Archiv-URL, abgerufen am 30. September 2021) ."},{"text":"„Der Dill wächst zwischen den Rosen, Tomaten- und Gurkengewächse bilden einen kleinen Dschungel, die Blumenvielfalt lässt bunte Sträuße wachsen.“","reference":"Blumenvielfalt lässt überall bunte Sträuße wachsen. In: Braunschweiger Zeitung. 3. August 2012 ."},{"text":"„Unsere Eltern sahen in der Schule das Tor zu einem besseren Leben. Dafür waren sie bereit, die Heimat aufzugeben und sich in den Dschungel von New York zu stürzen.“","reference":"David Chauvel: Cosa Nostra I. Die Anfänge. Schreiber & Leser, Hamburg 2008, ISBN 978-3-941-23900-5, Seite 13 ."}],"idioms":["das Gesetz des Dschungels"],"collocations":[],"derivations":["dschungelartig","Dschungelbewohner","Dschungelbuch","Dschungelcamp","Dschungeldickicht","Dschungeldorf","Dschungelexpedition","Dschungelfieber","Dschungelgebiet","Dschungelgestrüpp","Dschungelinsel","Dschungelkampf","Dschungelkämpfer","Dschungelkatze","Dschungelkrankheit","Dschungelkrieg","Dschungelland","Dschungellandschaft","Dschungelpfad","Dschungelpflanze","Dschungelregion","Dschungeltier","Dschungeltiger","Dschungeltour","Dschungeltraining","Dschungelwald"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Dschungel","id":"cbecbf5b8e1d5b"},"0064-0073:0e0f36461f7e18":{"word":"DSL","partOfSpeech":"Abkürzung","gender":"das","hyphenation":{"de-CH":"DSL","de-DE":"DSL"},"forms":[{"form":"DSL","tags":["Nominativ","Singular"]},{"form":"DSLs","tags":["Genitiv","Singular"]}],"senses":[{"definition":"eine breitbandige digitale Verbindung über das Telefonnetz"},{"definition":"eine sehr kleine Linux-Distribution, von 2003, jetzt eingestellt"},{"definition":"ein Verfahren zur Chipherstellung"},{"definition":"eine Modellierungssprache für ein Softwaresystem, domänenspezifische Sprache"}],"synonyms":[],"origins":["[1] Abkürzung für Digital Subscriber Line","[2] Abkürzung für Damn Small Linux","[3] Abkürzung für Dual Stress Liner","[4] Abkürzung für Domain Specific Language"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"DSL","id":"0e0f36461f7e18"},"0064-0073:0b72466930f7ec":{"word":"dschibutisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"dschi·bu·tisch","de-DE":"dschi·bu·tisch"},"forms":[{"form":"dschibutisch","tags":["Positiv"]},{"form":"dschibutische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"dschibutischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"dschibutischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"dschibutischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"dschibutisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist dschibutisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist dschibutisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist dschibutisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind dschibutisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"Adjektiv zu Dschibuti, Dschibuti betreffend"}],"synonyms":[],"origins":["vom Landesnamen Dschibuti mit Derivatem -isch abgeleitet"],"examples":[{"text":"Er spielt in der dschibutischen Nationalmannschaft.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"dschibutisch","id":"0b72466930f7ec"},"0064-0073:b5dbd1f11ff95e":{"word":"Dschibutier","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschi·bu·tier","de-DE":"Dschi·bu·tier"},"forms":[{"form":"Dschibutier","tags":["Nominativ","Singular"]},{"form":"Dschibutiern","tags":["Dativ","Plural"]},{"form":"Dschibutiers","tags":["Genitiv","Singular"]},{"form":"Dschibutierin","tags":["feminine"]}],"senses":[{"definition":"Staatsbürger von Dschibuti"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschibutier","id":"b5dbd1f11ff95e"},"0064-0073:33d4a2b2d8cde8":{"word":"Dschibutierin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschi·bu·tie·rin","de-DE":"Dschi·bu·tie·rin"},"forms":[{"form":"Dschibutier","tags":["masculine"]},{"form":"Dschibutierin","tags":["Nominativ","Singular"]},{"form":"Dschibutierinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Staatsbürgerin von Dschibuti"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschibutierin","id":"33d4a2b2d8cde8"},"0064-0073:b793f6c53dd8e9":{"word":"Dschihad","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschi·had","de-DE":"Dschi·had"},"forms":[{"form":"Jihad","tags":["alternative"]},{"form":"Djihad","tags":["alternative"]},{"form":"Dschihad","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Kampf gegen das Böse im Inneren eines Menschen, um eine moralische Vervollkommnung zu erreichen"},{"definition":"(kriegerischer) Kampf einer muslimischen Gemeinschaft gegen einen Feind, für gewöhnlich zum Zwecke der Verteidigung"},{"definition":"gewaltsame und teils terroristische Kriegsführung durch islamistische Extremisten mit dem Zweck der Verbreitung islamistischen Gedankenguts"}],"synonyms":[],"origins":["Entlehnung aus dem Arabischen: جِهَاد (DMG: ǧihād) ‚zielgerichtetes Mühen‘"],"examples":[{"text":"Dschihad wird häufig sinnentstellend mit „Heiliger Krieg“ übersetzt.","reference":""},{"text":"In Tunesien wurde der Kampf gegen den Analphabetismus Dschihad genannt.","reference":""},{"text":"„Auch wenn sie allesamt der muslimischen Welt angehören, ob geografisch oder religiös, heißt das noch lange nicht, dass sie sich gemeinsam in einem gewaltigen heiligen Glaubenskrieg zusammenschließen werden, um allein gegen den amerikanischen, den westlichen, den christlichen Gegner zu kämpfen: im „Dschihad“ in seiner aggressiven Interpretation.[…] Durch die zunehmende Manipulation der Auslegung wurde eben auch ein Begriff wie Dschihad zugleich emotionalisiert und eingeengt.“","reference":"Online-Ausgabe der Süddeutsche Zeitung, „Dschihad“ - Das missverständliche Wort Gottes , 21.09.2001"},{"text":"„Er sagte, der Islam eigne sich nicht für politischen Aktionismus, und dass die Muslimbrüder den Begriff Dschihad zu eng interpretierten, denn Dschihad bedeute in erster Linie persönliche Anstrengung.“","reference":"Hamed Abdel-Samad: Mein Abschied vom Himmel. Aus dem Leben eines Muslims Deutschland. Knaur Taschenbuch Verlag, München 2010, ISBN 978-3-426-78408-2, Seite 200 ."},{"text":"„Die Besetzung Afghanistans durch sowjetische Truppen hatte zudem eine Betonung der religiösen Dimension zur Folge, denn nun galt die Verteidigung gegen die Eindringlinge als Dschihad.“","reference":"Katja Mielke/Conrad Schetter: Pakistan: Land der Extreme. 1. Auflage. C.H.Beck, München 2013, ISBN 978-3-406-65295-0, Seite 215 ."},{"text":"„Nachdem er den Leuten, die Freiwillige in den Irak schleusten, gesagt hatte, er wolle in den Dschihad ziehen, hörte er sechs Monate nichts.“","reference":"deutschsprachige Online-Ausgabe der Le Monde diplomatique, Die zweite Wanderung des Terrors, 12.12.2008"},{"text":"„Theologisch ist Awlaki nicht besonders beschlagen, aber er ist intelligent, spricht fließend Englisch und kennt die Kultur der \"Ungläubigen\". Er weiß, wie seine Schüler den militanten Dschihad in der westlichen Welt ausüben können, er ist der perfekte Übersetzer. So sieht er auch sich selbst: \"Die Einzigen, die sich die Mühe machen und Geld dafür ausgeben, Dschihad-Literatur ins Englische zu übertragen, sind die westlichen Geheimdienste\", schreibt er auf seiner Website im Januar 2009.“","reference":"Online-Ausgabe des Magazins »Der Spiegel«, Jemen - Der Übersetzer des Dschihad, 11.01.2010"}],"idioms":[],"collocations":[],"derivations":["dschihadistisch","Dschihad-Literatur","Dschihad-Unterstützer","Dschihadi","Dschihadismus","Dschihadist"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschihad","id":"b793f6c53dd8e9"},"0064-0073:aa049a10730ad2":{"word":"Dschibuti","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Dschi·bu·ti","de-DE":"Dschi·bu·ti"},"forms":[{"form":"Dschibutis","tags":["Genitiv","Singular"]},{"form":"des Dschibuti","tags":["Genitiv","Singular"]},{"form":"des Dschibutis","tags":["Genitiv","Singular"]},{"form":"(das) Dschibuti","tags":["Nominativ","Singular"]},{"form":"(dem) Dschibuti","tags":["Dativ","Singular"]}],"senses":[{"definition":"Staat in Ostafrika"},{"definition":"Stadt im gleichnamigen Staat, gleichzeitig dessen Hauptstadt"}],"synonyms":["Republik Dschibuti"],"origins":[],"examples":[{"text":"Das Klima Dschibutis ist heiß und trocken.","reference":""},{"text":"„Dschibuti ist der Endpunkt der Eisenbahnlinie von Addis Abeba und Freihafen für Äthiopien, das keinen eigenen Zugang zum Meer hat.“","reference":"Wikipedia-Artikel „Dschibuti (Stadt)“"}],"idioms":[],"collocations":[],"derivations":["Dschibutier","Dschibutierin","dschibutisch"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Dschibuti","id":"aa049a10730ad2"},"0064-0073:ae5c6b095bb5a5":{"word":"Dschellaba","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschel·la·ba","de-DE":"Dschel·la·ba"},"forms":[{"form":"Dschellaba","tags":["Nominativ","Singular"]},{"form":"Dschellabas","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weites, wollenes nordafrikanisches Kleidungsstück mit Kapuze (für Männer und Frauen)"}],"synonyms":[],"origins":["Das Wort wurde aus arabischem جُلَّّابَة (DMG: ǧullāba)^(→ar) entlehnt."],"examples":[{"text":"Er trug eine Dschellaba.","reference":""},{"text":"„Vers 59 der 33. Sure, ‚Die Parteien‘: ‚Prophet, sag deinen Frauen und deinen Töchtern und allen Frauen der Gläubigen, dass sie die Dschellaba tragen sollen. Dies ist besser so, damit die Leute wissen, dass es sich um ehrbare Personen handelt und sie nicht belästigt werden.‘ Diesen Vers zitieren die Fundamentalisten am häufigsten, um das Tragen des Schleiers zu rechtfertigen. Es gibt sogar Übersetzungen, die von radikalen muslimischen Übersetzern absichtlich verfälscht wurden, denn sie schreiben ‚Schleier‘ anstatt ‚Dschellaba‘. - Die klassische arabische Dschellaba ist aber ein Kleidungsstück, das von den Schultern bis zu den Füssen reicht und den Kopf freilässt.“","reference":"Dass Frauen sich verschleiern. In: NZZ am Sonntag. 18. April 2004, Seite 23 ."},{"text":"„Währenddessen gaffte ich die Berberin, deren schmale Finger am Ärmel ihrer indigofarbenen Dschellaba zupften, unverwandt an.“","reference":"Ronald Pohl: Die algerische Verblendung. Roman. Literaturverlag Droschl, Graz 2007, ISBN 978-3-85420-715-3, Seite 86 (Zitiert nach Google Books) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschellaba","id":"ae5c6b095bb5a5"},"0064-0073:7ca9370bb683d8":{"word":"Ds","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"Ds","de-DE":"Ds"},"forms":[],"senses":[{"definition":"chemisches Symbol für Darmstadtium"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ds","id":"7ca9370bb683d8"},"0064-0073:94d5a891b3197a":{"word":"dschihadistisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"dschi·ha·dis·tisch","de-DE":"dschi·ha·dis·tisch"},"forms":[{"form":"jihadistisch","tags":["alternative"]},{"form":"dschihadistisch","tags":["Positiv"]},{"form":"dschihadistische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"dschihadistischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"dschihadistischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"dschihadistischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"dschihadistisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist dschihadistisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist dschihadistisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist dschihadistisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind dschihadistisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"den Dschihad und seine Grundsätze betreffend"},{"definition":"auf den Grundsätzen des Dschihad aufbauend, fußend"},{"definition":"Tendenzen einer zumeist aggressiven, fundamentalistischen Auslegung des Dschihad zeigend"}],"synonyms":["islamistisch","salafistisch","wahhabitisch"],"origins":["Ableitung eines Adjektivs zum Substantiv Dschihad mit den Derivatemen (Ableitungsmorphemen) -ist und -isch"],"examples":[{"text":"„Erfolgt allerdings keine produktive Auflösung steht zu befürchten, dass dschihadistische Grundsätze wie der des palästinensischen Dschihad-Theoretikers ʽAbdallāh ʽAzzām weiter einflussreich bleiben, dass alle sunnitischen Rechtsschulen die Auffassung teilen, Dschihad sei der Kampf (qitāl) und Hilfe im Kampf (al-ʽaun fīhī) (ʽAzzām 2006: 1).“","reference":"Rüdiger Lohlker: Islam und Gewalt. In: Innsbrucker Diskussionspapiere zu Weltordnung, Religion und Gewalt (IDWRG), Nummer 15/2007. Seite 13"},{"text":"„Mit dem Begriff Haus des Friedens, englisch lässt Cerić “House of Peace” sagen, frz. “la demeure de la paix”, hat uns der listige bosnische Gelehrtenführer das arabische dār, wörtlich Haus, gemeint ist das irdische Territorium in seiner Relation zu Allahgott, in die Diskussion hinein geschmuggelt, das uns aus der manichäisch und dschihadistisch verstandenen Benennung des islamisch beherrschten Gebietes als dār al-islām bekannt ist.“","reference":"eingsehen am 03.02.2010"},{"text":"„Chomeini hat die Religion der Schiiten, die Schia, die über Jahrhunderte für Gewaltlosigkeit und Quietismus stand, dschihadistisch radikalisiert.“","reference":"Online-Ausgabe des Magazins »Der Spiegel«, Bassidsch-Brigaden - \"Wir lieben den Tod\", 29.06.2006"},{"text":"„Islamisten, ob friedlich oder dschihadistisch orientiert, wollen eine andere Ordnung als die des Rechtsstaates und der Demokratie durchsetzen.“","reference":"Online-Ausgabe der Die Welt, Grenzen der Toleranz, 05.09.2004"},{"text":"„In diesem Kontext galt die Hisbollah nur noch als verlängerter Arm dieser neuen \"Ablehnungsfront\" gegen die Politik des Westens in der Region. Die mittlerweile notorische Kritik am Iran und der libanesischen Hisbollah, aber auch der (durch die labile Situation im Libanon begünstigte) Versuch des Westens, das syrische Regime in die Zange zu nehmen, geben der antiwestlichen Rhetorik in der arabischen und muslimischen Welt nur neue Nahrung. Damit stärkt der Westen den \"politischen Islam\" in all seinen Formen, ob moderat, radikal oder dschihadistisch.“","reference":"deutschsprachige Online-Ausgabe der Le Monde diplomatique, Die Dynamik des islamischen Aufbegehrens - Religion und Nationalismus von Palästina bis Iran, 10.03.2006"},{"text":"„Die dschihadistische Strömung ist nicht isoliert zu sehen. Sie steht in ständiger Auseinandersetzung mit anderen zeitgenössischen islamischen Strömungen. Neuere Versuche, dschihadistische Bewegungen auch argumentativ entgegenzutreten, die es vom Jemen über Saudi-Arabien bis nach Südostasien gibt, zeigen uns, dass auch sunnitische religiöse Gelehrte (und Regierungen wie die saudische) die Notwendigkeit einer solchen Auseinandersetzung sehen.“","reference":"Rüdiger Lohlker: Islam. Eine Ideengeschichte, 1. Auflage, facultas.wuv UTB, Wien 2008. Seite 257 ISBN 9783825230784"},{"text":"„Bis zur Invasion der US-Truppen im Irak hatte die dschihadistische Bewegung keinen größeren Einfluss auf die zentralen Werte, Anliegen und Kämpfe in der arabischen Welt.[…]Die Debatte über die Rolle der dschihadistischen Bewegungen und die Frage, warum sie den wichtigsten Kampf der arabisch-muslimischen Welt ignoriert, begann bereits mit dem afghanischen Dschihad und ist bis heute relevant geblieben.“","reference":"deutschsprachige Online-Ausgabe der Le Monde diplomatique, Die zweite Wanderung des Terrors, 12.12.2008"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"dschihadistisch","id":"94d5a891b3197a"},"0064-0073:b62a78c206c72b":{"word":"Dschaina","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschai·na","de-DE":"Dschai·na"},"forms":[{"form":"Jina","tags":["variant"]},{"form":"Jaina","tags":["alternative"]},{"form":"Dschina","tags":["variant"]},{"form":"Dschaina","tags":["Nominativ","Singular"]},{"form":"Dschainas","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Anhänger des Dschainismus"}],"synonyms":[],"origins":["Entlehnung aus sanskrit जिन (jina) ^(→ sa) „Buddha“"],"examples":[{"text":"„‚Indien war von jeher ein riesiger Bilderbasar‘, so Joël Farges(2), Produzent von Adoor Gopalakrishnan, einem Filmemacher aus Kerala. ‚Von den Mandalas der Dschaina bis zu den Thangkas - buddhistischen Rollbildern aus Tibet -, von den Schattenspielen bis zu den klassischen Bharata-Natyam-Tänzen bringt es seit seiner Frühgeschichte Bilder seiner Götter und Darstellungen der um sie gesponnenen Geschichten hervor.‘“","reference":"Online-Ausgabe der Le Monde diplomatique, Realismus in Bollywood - Possenreißer und gequälte Witwen, 13.08.2004"}],"idioms":[],"collocations":[],"derivations":["Dschainismus","dschainistisch"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschaina","id":"b62a78c206c72b"},"0064-0073:e2f2bfac77be6d":{"word":"Dschina","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschi·na","de-DE":"Dschi·na"},"forms":[{"form":"Dschina","tags":["Nominativ","Singular"]},{"form":"Dschinas","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Religion: Nebenform von Dschaina"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":["Dschinismus","dschinistisch"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschina","id":"e2f2bfac77be6d"},"0064-0073:57c5147e89925e":{"word":"Dschenin","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Dschen·in","de-DE":"Dschen·in"},"forms":[{"form":"Jenin","tags":["alternative"]},{"form":"Djenin","tags":["alternative"]},{"form":"Dschenins","tags":["Genitiv","Singular"]},{"form":"des Dschenin","tags":["Genitiv","Singular"]},{"form":"des Dschenins","tags":["Genitiv","Singular"]},{"form":"(das) Dschenin","tags":["Nominativ","Singular"]},{"form":"(dem) Dschenin","tags":["Dativ","Singular"]}],"senses":[{"definition":"palästinensische Stadt im von Israel besetzten Westjordanland"}],"synonyms":[],"origins":[],"examples":[{"text":"„Der Bus hielt in Dschenin, einer rein arabischen Stadt.“","reference":"Tom Segev: Es war einmal ein Palästina. Juden und Araber vor der Staatsgründung Israels. Siedler, München 2005, ISBN 978-3-886-80805-2, Seite 254 ."},{"text":"„Die Armee sei mit etwa 30 Geländewagen in das Flüchtlingslager von Dschenin eingedrungen und habe mit Razzien begonnen.“","reference":"Björn Hengst: Israel rückt erneut in Nablus ein. In: Spiegel Online. 28. Februar 2007, ISSN 0038-7452 (URL, abgerufen am 16. Februar 2013) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschenin","id":"57c5147e89925e"},"0064-0073:36ba6c9cb8f176":{"word":"Dschunke","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschun·ke","de-DE":"Dschun·ke"},"forms":[{"form":"Dschunke","tags":["Nominativ","Singular"]},{"form":"Dschunken","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Segelschiff chinesischer Bauart"}],"synonyms":[],"origins":["im 16. Jahrhundert vom malaiischen djung „großes Schiff“ entlehnt. „Entlehnung ins Deutsche wohl über englische und portugiesische Vermittlung.“"],"examples":[{"text":"„Noch am Abend dieses Tages machten wir Jagd auf eine zweite Dschunke, einen Zweimaster, der in ansehnlicherem Zustand zu sein schien als das erste Fahrzeug.“","reference":"Daniel Defoe: Das Leben, die Abenteuer und die Piratenzüge des berühmten Kapitän Singleton. Verlag Neues Leben, Berlin 1985, ISBN - , Seite 155."},{"text":"„Miau Tjing hielt sich auf dem Deck der Dschunke auf.“","reference":"Djin Ping Meh. Schlehenblüten in goldener Vase. Band 3, Ullstein, Berlin/Frankfurt am Main 1987 (übersetzt von Otto und Artur Kibat), ISBN 3-549-06673-2, Seite 49 . Chinesisches Original 1755."},{"text":"„Sie standen dort in einem weiten Raum, grün und kantig, ausgegraben nach tausend Jahren und jetzt von Licht umflutet wie Dschunken in einem weißen Meer oder wie grüne und blaue Felsen von Urgestein.“","reference":"Erich Maria Remarque: Das gelobte Land. Roman (Fragment). Kiepenheuer & Witsch, Köln 1998, ISBN 3-462-02695-X, Seite 305. Grundlage des Textes: Manuskript 1970."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschunke","id":"36ba6c9cb8f176"},"0064-0073:da236f29574f2f":{"word":"Dschuba","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Dschuba","de-DE":"Dschuba"},"forms":[{"form":"Juba","tags":["alternative"]},{"form":"Dschubas","tags":["Genitiv","Singular"]},{"form":"des Dschuba","tags":["Genitiv","Singular"]},{"form":"des Dschubas","tags":["Genitiv","Singular"]},{"form":"(das) Dschuba","tags":["Nominativ","Singular"]},{"form":"(dem) Dschuba","tags":["Dativ","Singular"]}],"senses":[{"definition":"Hauptstadt von Südsudan"}],"synonyms":[],"origins":[],"examples":[{"text":"Seit einigen Jahren lebt er in Dschuba.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschuba","id":"da236f29574f2f"},"0064-0073:9e0bce66eafe55":{"word":"Dschihadist","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschi·ha·dist","de-DE":"Dschi·ha·dist"},"forms":[{"form":"Jihadist","tags":["alternative"]},{"form":"Dschihadist","tags":["Nominativ","Singular"]},{"form":"Dschihadisten","tags":["Nominativ","Plural"]},{"form":"Dschihadistin","tags":["feminine"]}],"senses":[{"definition":"Anhänger und Kämpfer des Dschihad"}],"synonyms":["Gotteskrieger","Islamist","radikaler Muslim"],"origins":["Ableitung (Derivation) des Substantivs Dschihad mit dem Suffix -ist als Derivatem (Ableitungsmorphem)"],"examples":[{"text":"„Ausländische Dschihadisten erstarken und rivalisieren mit anderen Rebellengruppen.“","reference":"Oliver Trenkamp: Krieg in Syrien: Kämpfe zwischen Rebellen und Dschihadisten eskalieren. In: Spiegel Online. 13. Juli 2013, ISSN 0038-7452 (URL, abgerufen am 13. Juli 2013) ."}],"idioms":[],"collocations":[],"derivations":["Dschihadisten-Familie","Dschihadistenführer","Dschihadistengruppe","Dschihadisten-Hauptquartier","Dschihadisten-Prozess","Dschihadisten-Schmiede"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Dschihadist","id":"9e0bce66eafe55"},"0064-0073:2efb0aee6fb646":{"word":"Dschihadistin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschi·ha·dis·tin","de-DE":"Dschi·ha·dis·tin"},"forms":[{"form":"Jihadistin","tags":["alternative"]},{"form":"Dschihadist","tags":["masculine"]},{"form":"Dschihadistin","tags":["Nominativ","Singular"]},{"form":"Dschihadistinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Anhängerin und Kämpferin des Dschihad"}],"synonyms":[],"origins":["Ableitung (Derivation) (Motion, Movierung) des Femininums aus der maskulinen Form Dschihadist mit dem Suffix -in als Derivatem (Ableitungsmorphem)"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschihadistin","id":"2efb0aee6fb646"},"0064-0073:76277541964bab":{"word":"Dschungelwald","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschun·gel·wald","de-DE":"Dschun·gel·wald"},"forms":[{"form":"Dschungelwald","tags":["Nominativ","Singular"]},{"form":"Dschungelwalde","tags":["Dativ","Singular"]},{"form":"Dschungelwalds","tags":["Genitiv","Singular"]},{"form":"Dschungelwaldes","tags":["Genitiv","Singular"]},{"form":"Dschungelwälder","tags":["Nominativ","Plural"]},{"form":"Dschungelwäldern","tags":["Dativ","Plural"]}],"senses":[{"definition":"dichter tropischer oder subtropischer Sumpfwald"}],"synonyms":[],"origins":["Determinativkompositum aus Dschungel und Wald"],"examples":[{"text":"„Im Jahre 1959 begannen die Bauernsoldaten Nordvietnams damit, den so genannten Ho-Chi-Minh-Pfad durch die Dschungelwälder von Laos zu schlagen; das Netz der Wege füllte sich mit Guerillakämpfern und Spionen, die alle Richtung Südvietnam marschierten.“","reference":"Tim Weiner: CIA. Die ganze Geschichte. 6. Auflage. Fischer Taschenbuch Verlag, Frankfurt am Main 2012, ISBN 978-3596178650, Seite 288"},{"text":"„Im mexicanischen Bundesstaat Chiapas, in Guatemala und in Belize ist im Tiefland das Klima tropisch, ausgedehnte Dschungelwälder prägen hier das Landschaftsbild.“","reference":"Wikipedia-Artikel „Maya“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelwald","id":"76277541964bab"},"0064-0073:91a0a7f90ad35f":{"word":"Dschungelpfad","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschun·gel·pfad","de-DE":"Dschun·gel·pfad"},"forms":[{"form":"Dschungelpfad","tags":["Nominativ","Singular"]},{"form":"Dschungelpfade","tags":["Nominativ","Plural"]},{"form":"Dschungelpfads","tags":["Genitiv","Singular"]},{"form":"Dschungelpfaden","tags":["Dativ","Plural"]},{"form":"Dschungelpfades","tags":["Genitiv","Singular"]}],"senses":[{"definition":"schmaler Weg, der durch einen Dschungel führt"}],"synonyms":[],"origins":["Determinativkompositum aus Dschungel und Pfad"],"examples":[{"text":"„Die CIA machte sich ans Werk und kaufte sich zunächst eine neue laotische Regierung, dann baute sie eine Guerillaarmee auf, die die Kommunisten bekämpfen und den Dschungelpfad angreifen sollte.“","reference":"Tim Weiner: CIA. Die ganze Geschichte. 6. Auflage. Fischer Taschenbuch Verlag, Frankfurt am Main 2012, ISBN 978-3596178650, Seite 289"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelpfad","id":"91a0a7f90ad35f"},"0064-0073:2f3c5cd763ceab":{"word":"DSV","partOfSpeech":"Abkürzung","gender":"der","hyphenation":{"de-CH":"DSV","de-DE":"DSV"},"forms":[{"form":"DSV","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Deutscher Schwimmverband/Deutscher Schwimm-Verband"},{"definition":"Deutscher Skiverband"},{"definition":"Deutscher Seglerverband/Deutscher Segler-Verband"}],"synonyms":[],"origins":[],"examples":[{"text":"„»Beim DSV passiert nichts. Beim DSV hat sich nichts verändert, und niemand will Veränderungen. Wir verschwenden viel Zeit, die wir nicht haben.«“","reference":"Steffen und Biedermann attackieren DSV. In: Welt Online. 21. November 2012, ISSN 0173-8437 (URL, abgerufen am 17. Februar 2014) ."},{"text":"Der DSV schickte keinen Teilnehmer zur Olympia-Abfahrt der Männer nach Sotschi.","reference":""},{"text":"„Theorie ist wichtig, aber der DSV sollte schleunigst die Anforderungen für die praktischen A- und BR-Schein-Prüfungen heraufsetzen.“","reference":"Von Törns und Tampen. In: Zeit Online. Nummer 27, 27. Juni 1975, ISSN 0044-2070 (URL, abgerufen am 17. Februar 2014) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"DSV","id":"2f3c5cd763ceab"},"0064-0073:89d421252382f5":{"word":"DSG","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"DSG","de-DE":"DSG"},"forms":[],"senses":[{"definition":"Direktschaltgetriebe"}],"synonyms":[],"origins":[],"examples":[{"text":"Ein DSG ist meist teuer.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"DSG","id":"89d421252382f5"},"0064-0073:26c667c3a8d00d":{"word":"Dschihadistengruppe","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschi·ha·dis·ten·grup·pe","de-DE":"Dschi·ha·dis·ten·grup·pe"},"forms":[{"form":"Dschihad-Gruppe","tags":["variant"]},{"form":"Dschihadistengruppe","tags":["Nominativ","Singular"]},{"form":"Dschihadistengruppen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"den Dschihadismus zu seinem Grundsatz gemachte Gruppe"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus dem Substantiv Dschihadist, dem Fugenelement -en und dem Substantiv Gruppe"],"examples":[{"text":"„Ein Selbstmordattentäter hatte am Grenzübergang Taba drei südkoreanische Urlauber sowie ihren Fahrer mit in den Tod gerissen. Zu der Tat bekannte sich die Dschihadistengruppe Ansar Beit al Makdess. Militante Islamisten hatten Urlaubern in Ägypten in der vergangenen Woche mit neuen Anschlägen gedroht und ihnen ein Ultimatum zum Verlassen des Landes bis Donnerstag vergangener Woche gestellt.“","reference":"Dschihadistengruppe. DWDS, 27. Februar 2014, archiviert vom Original am 27. Februar 2014 abgerufen am 7. Oktober 2014 (HTML, Deutsch, Quelle: Die Zeit).Parameter „archiv-url“ darf ausschließlich mit dem Parameter „archiv-datum“ zusammen verwendet werden. (Hilfe)"},{"text":"„Irakische Sicherheitskräfte haben nach eigenen Angaben in der Provinz Anbar 55 Kämpfer getötet, die der Terrororganisation Al-Kaida nahestehen sollen. General Ali Ghaidan Madscheed, Kommandeur der Bodentruppen, sagte, die Aufständischen seien am Abend bei zwei Einsätzen gegen die Dschihadistengruppe Islamischer Staat im Irak und der Levante (ISIL) nahe den seit Tagen umkämpften Städten Ramadi und Falludscha getötet worden. Bei dem ersten Einsatz nahe Ramadi seien 25 Kämpfer ums Leben gekommen.“","reference":"Dschihadistengruppe. DWDS, 5. Januar 2014, archiviert vom Original am 5. Januar 2014 abgerufen am 7. Oktober 2014 (HTML, Deutsch, Die Zeit).Parameter „archiv-url“ darf ausschließlich mit dem Parameter „archiv-datum“ zusammen verwendet werden. (Hilfe)"},{"text":"„Bei den Luftangriffen der US-geführten Koalition gegen die Dschihadistengruppe Islamischer Staat (IS) in Syrien sind nach Angaben von Aktivisten schon mehr als 550 Menschen getötet worden.“","reference":"Syrien: Hunderte Tote bei Luftangriffen. In: Bild.de. (URL, abgerufen am 14. Februar 2014) ."},{"text":"„In Syrien sind seit dem Beginn der US-geführten Offensive gegen die Dschihadistengruppe vor einer Woche nach Angaben von Aktivisten bereits mehr als 200 Extremisten getötet worden.“","reference":"Peschmerga-Miliz - Kurden starten Offensive gegen IS-Terroristen im Irak. In: FOCUS Online. ISSN 0943-7576 (URL, abgerufen am 14. Februar 2014) ."},{"text":"„Das kanadische Parlament hat einem Militäreinsatz im Kampf gegen die Dschihadistengruppe \" Islamischer Staat\" (IS) zugestimmt.“","reference":"Kampf gegen IS: Kanada will sich an Luftangriffen beteiligen. In: Spiegel Online. ISSN 0038-7452 (URL, abgerufen am 14. Februar 2014) ."},{"text":"„Die Dschihadistengruppe Islamischer Staat (IS) hat offenbar einen weiteren als Geisel genommenen US-Journalisten grausam hingerichtet.“","reference":"Dschihadistengruppe IS enthauptet offenbar weiteren US-Reporter. In: Welt Online. ISSN 0173-8437 (URL, abgerufen am 14. Februar 2014) ."},{"text":"„Viele ausländische Kämpfer der Dschihadistengruppe kommen über die Türkei nach Syrien.“","reference":"IS-Terror - Ahmet Davutoğlus größte Herausforderung. In: Zeit Online. ISSN 0044-2070 (URL, abgerufen am 14. Februar 2014) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschihadistengruppe","id":"26c667c3a8d00d"},"0064-0073:9de9f5190ff437":{"word":"Dschihadismus","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschi·ha·dis·mus","de-DE":"Dschi·ha·dis·mus"},"forms":[{"form":"Jihadismus","tags":["alternative"]},{"form":"Djihadismus","tags":["alternative"]},{"form":"Dschihadismus","tags":["Nominativ","Singular"]}],"senses":[{"definition":"militante extremistische Strömung, die mithilfe des Dschihad ihre politischen Ziele erreichen möchte"}],"synonyms":["Jihadismus"],"origins":[],"examples":[{"text":"„Hier können sie ihre diplomatischen Stärken ausspielen: vermitteln, verzögern, verwässern. Die russischen Eliten wollen die Welt nicht heilen, sondern nur sicherstellen, dass Russland von den globalen Gebrechen verschont wird, vor allem von dem islamischen Dschihadismus vom Kaukasus bis nach Syrien. Russland spielt sich deshalb oft weniger als Ordnungs- denn als Verhinderungsmacht auf.“","reference":"Dschihadismus. DWDS, 30. September 2013, archiviert vom Original am 30. September 2013 abgerufen am 7. Oktober 2014 (HTML, Deutsch, Quelle: Die Zeit).Parameter „archiv-url“ darf ausschließlich mit dem Parameter „archiv-datum“ zusammen verwendet werden. (Hilfe)"},{"text":"„Ein geistreicher und witziger Roman über eine unselige Zeit, in der die Wiedereinführung der Scharia und der moderne Dschihadismus wurzeln.“","reference":"Dschihadismus. Wotschatz Lexikon Uni Leipzig, 17. Januar 2011, archiviert vom Original am 17. Januar 2011 abgerufen am 7. Oktober 2014 (HTML, Deutsch, Quelle: Neue Zürcher Zeitung).Parameter „archiv-url“ darf ausschließlich mit dem Parameter „archiv-datum“ zusammen verwendet werden. (Hilfe)"}],"idioms":[],"collocations":[],"derivations":["Dschihadismus-Experte"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Dschihadismus","id":"9de9f5190ff437"},"0064-0073:aadef347155467":{"word":"Dschihadistenmiliz","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschi·ha·dis·ten·mi·liz","de-DE":"Dschi·ha·dis·ten·mi·liz"},"forms":[{"form":"Dschihadistenmiliz","tags":["Nominativ","Singular"]},{"form":"Dschihadistenmilizen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Miliz der Dschihadisten, die mit militärischen Mitteln ihre politischen Ziele erreichen möchten"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus dem Substantiv Dschihadist, dem Fugenelement -en und dem Substantiv Miliz"],"examples":[{"text":"„Die Türkei weigerte sich über lange Zeit, die internationale Koalition gegen IS zu unterstützen. Doch da die Dschihadistenmiliz zunehmend an die Grenze heranrückt und den kurdischen Kämpfern in Syrien offenbar überlegen ist, leitete Präsident Recep Tayyip Erdoğan einen Kurswechsel ein – nicht zuletzt auf Druck des Anti-IS-Bündnisses rund um die USA.“","reference":"satseve: Bewohner von Ain al-Arab befürchten Massaker durch IS: Türkei verlegt Panzer an Grenze. 30. September 2014, archiviert vom Original am 30. September 2014 abgerufen am 10. Oktober 2014 (HTML, Deutsch)."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschihadistenmiliz","id":"aadef347155467"},"0064-0073:516033238334e8":{"word":"Dschungelcamp","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Dschun·gel·camp","de-DE":"Dschun·gel·camp"},"forms":[{"form":"Dschungelcamp","tags":["Nominativ","Singular"]},{"form":"Dschungelcamps","tags":["Nominativ","Plural"]}],"senses":[{"definition":"im Urwald errichtetes Lager"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Camp"],"examples":[{"text":"Zu Regenzeiten kann ein Dschungelcamp auch mal überfluten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelcamp","id":"516033238334e8"},"0064-0073:7ef5a08fd8f181":{"word":"Dschinn","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschinn","de-DE":"Dschinn"},"forms":[{"form":"Ginn","tags":["alternative","archaic"]},{"form":"Jinn","tags":["alternative"]},{"form":"Dschinn","tags":["Nominativ","Singular"]},{"form":"Dschinns","tags":["Nominativ","Plural"]},{"form":"Dschinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"(im muslimisch-orientalischen Kontext) nach (vor-)islamischer Vorstellung ein übersinnliches, ins menschliche Leben schädlich oder helfend eingreifendes Geisterwesen, das in aller Regel für den Menschen unsichtbar ist, jedoch mitunter diesem in menschlicher oder tierischer Gestalt sichtbar werden kann (dem Koran zufolge ist es ein aus rauchlosem Feuer erschaffenes Mittelwesen zwischen den Menschen und den Engeln und gehört mit diesen beiden zu den vernünftigen Wesen; dem islamischen Volksglauben nach kann es auch Besitz vom Menschen ergreifen)"}],"synonyms":["Flaschengeist"],"origins":["Das Wort geht auf das arabische Kollektivum جِنّ (DMG: ǧinn)^(→ar) ‚Dschinn Pl.; Geister‘ zurück, das entweder direkt aus dem Arabischen oder, als Vermittlersprache, aus dem Französischen ins Deutsche, wo es seit Anfang des 19. Jahrhunderts bezeugt ist, entlehnt worden ist."],"examples":[{"text":"„Sag: Mir ist (als Offenbarung) eingegeben worden, daß eine Schar Dschinn (mir beim Vortrag des Korans) zuhörten und daraufhin (zu ihren Artgenossen) sagten: […]“","reference":"Koran: Sure 72, Vers 1 (Zitiert nach Corpus Coranicum, abgerufen am 11. März 2021.)"},{"text":"„Schahrijars Ring setzt viel Wissen über den Islam voraus, doch vieles ist dem westlichen Leser auch bekannt, etwa die bösen und die guten Dschinn oder Geister, die auch in der Bibel eine Rolle spielen.“","reference":"Celal Özcan: Der neue Roman des Bosniers Dzevad Karahasan. In: Frankfurter Rundschau. 24. Januar 1998, ISSN 0940-6980, Seite 4 ."},{"text":"„Die Hände der Dschinnen machten sich an meinem Körper zu schaffen.“","reference":"Iman Humaidan-Junis: B wie Bleiben wie Beirut. Lenos Verlag, Basel 2007 (Originaltitel: باء مثل بيت مثل بيروت, übersetzt von Hartmut Fähndrich aus dem Arabischen), ISBN 978-3-85787-384-3, Seite 71 ."},{"text":"„Man konnte beinahe die unsichtbare Faust des eifersüchtigen Dschinns sehen, wenn sie Großvaters Kinn traf.“","reference":"Rafik Schami: Die Frau, die ihren Mann auf dem Flohmarkt verkaufte oder wie ich zum Erzähler wurde. Carl Hanser Verlag, München 2011, ISBN 978-3-446-23771-1, Seite 9 (Zitiert nach Google Books) ."},{"text":"„Ein böser Dschinn hatte sie in ein liebloses arabisches Frühstück verhext, das allmorgendlich, wenn die Sonne die Dachterrasse erwärmte, in einem dort oben errichteten Häuschen hingestellt wurde.“","reference":"Wolfgang Büscher: Ein Frühling in Jerusalem. Rowohlt Berlin Verlag, Berlin 2014, ISBN 978-3-87134-784-9, Seite 63 ."},{"text":"„Sein Attentat hatte Wellen geschlagen, aber Stern hatte keinen Helden erzeugt, sondern den Dschinn aus der Flasche gelassen.“","reference":"Katja Petrowskaja: Vielleicht Esther. Geschichten. Suhrkamp, Berlin 2014, ISBN 978-3-518-42404-9, Seite 175 ."},{"text":"„So einen Ort gibt es in der Stadt nicht, aber außerhalb ihrer Mauern, vielleicht so 500 Meter von ihnen entfernt, steht eine uralte Ruine, in die niemand mehr geht, weil alle glauben, dass ein Dschinn in ihr wohnt.“","reference":"Helge Timmerberg: Die Märchentante, der Sultan, mein Harem und ich. Ungekürzte Taschenbuchausgabe, Malik, München 2015, ISBN 978-3-492-40582-9, Seite 224 (Erstausgabe 2014) ."},{"text":"„Und die Hyänen dienen nicht nur als Orakel und kostenlose Müllabfuhr, sie säubern die Stadt auch noch von Dschinns.“","reference":"Philipp Hedemann: Der Mann, der den Tod auslacht. Begegnungen auf meinen Reisen durch Äthiopien. 2., aktualisierte und erweiterte Auflage. DuMont Reiseverlag, Ostfildern 2017, ISBN 978-3-7701-8286-2, Seite 10 (Erstausgabe 2013) ."},{"text":"„In einer psychologischen Interpretation könnte man den Dschinn demnach auch als einen dunklen, unbewussten Teil bezeichnen, von dem sich der Mensch leicht verführen lässt, wenn er nicht für Klarheit sorgt. Mohammed selbst räumt im Koran ein, einen Dschinn zu haben, allerdings würde Gott ihm helfen, mit diesem umzugehen, sodass dieser nur zu Gutem rate. So ein guter Dschinn steigt auch aus Aladins Öllampe und verhilft ihm zu Reichtum und Macht. Ein gefährlicher Dschinn wiederum schlüpft aus der Flasche, die der Fischer in Tausendundeine Nacht aus dem Meer zieht.“","reference":"Adelheid Wölfl: Verführer, Einflüsterer und Urväter der Fake-News. In: DER STANDARD. 17. Juni 2017, Seite 25 ."},{"text":"„Wir Frauen aber wissen es, wir wissen, dass es viele Dschinn geben wird, und auch, wo sie sich aufhalten: unter der Spüle, im Badezimmer, hinter dem Wassertank aus Blech, über dem Küchenverschlag, unter den Betten der einsamen Frauen, hinter den Gardinen der Pubertierenden, die sich in ihren neuen Körpern nicht zurechtfinden, in den Schränken der Kinder …“","reference":"Rabab Haidar: Semimänner, Halbfrauen und ganze Hyänen. Ein Versprechen. In: WeiterSchreiben.jetzt. [2019] (Originaltitel: وعدٌ بأشباه رجال، أنصاف نساء وضباع كاملة, übersetzt von Christine Battermann aus dem Arabischen) (URL, abgerufen am 11. März 2021) ."},{"text":"„Laut dem Koran sind Dschinn Geister, die tausend Jahre vor Adam erschaffen wurden. Der aus schwarzem Lehm erschaffene Mensch ist ein sichtbares Wesen, der aus rauchlosem Feuer erschaffene Dschinn hingegen ist unsichtbar. Dschinn gibt es zuhauf, und sie unterscheiden sich voneinander in vielerlei Hinsicht. Manche sind böse.“","reference":"Elif Shafak: Schau mich an. Roman. 2. Auflage. Kein & Aber, Zürich/Berlin 2020 (Originaltitel: Mahrem, übersetzt von Gerhard Meier aus dem Türkischen), ISBN 978-3-0369-5829-3, Seite 162 (türkische Originalausgabe 1999; deutschsprachige Erstausgabe 2020) ."},{"text":"„Sie heißt Gharapuri, liegt zwischen Panvel und Manbai im Meer und ist ein grausiger Ort voller Dschinnen.“","reference":"Christine Wunnicke: Die Dame mit der bemalten Hand. Roman. 7. Auflage. Berenberg Verlag, Berlin 2020, ISBN 978-3-946334-76-7, Seite 164 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Dschinn","id":"7ef5a08fd8f181"},"0064-0073:af9ac956d840d2":{"word":"Dschingis Khan","partOfSpeech":"Eigenname","gender":"der","hyphenation":{"de-CH":"Dschin·gis Khan","de-DE":"Dschin·gis Khan"},"forms":[{"form":"des Dschingis Khan","tags":["Genitiv","Singular"]},{"form":"(dem) Dschingis Khan","tags":["Dativ","Singular"]},{"form":"(den) Dschingis Khan","tags":["Akkusativ","Singular"]},{"form":"(der) Dschingis Khan","tags":["Nominativ","Singular"]},{"form":"(des) Dschingis Khans","tags":["Genitiv","Singular"]}],"senses":[{"definition":"ehemaliger, mächtiger mongolischer Herrscher und Eroberer"}],"synonyms":[],"origins":[],"examples":[{"text":"„Schon beim bloßen Aussprechen seines Namens erzitterte zu Anfang des 13. Jahrhunderts ganz Zentralasien: Dschingis Khan gehörte zu den mächtigsten Herrschern seiner Zeit.“","reference":"wissen.de – Artikel „Wie hat Dschingis Khan es geschafft, das Chinesische Reich zu erobern?“"},{"text":"„Im Jahr 1227 erlag Dschingis Khan den Verletzungen, die er sich bei einem Unfall zugezogen hatte.“","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschingis Khan","id":"af9ac956d840d2"},"0064-0073:516c7caedaca3e":{"word":"Dschihadistenführer","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschi·ha·dis·ten·füh·rer","de-DE":"Dschi·ha·dis·ten·füh·rer"},"forms":[{"form":"Dschihadistenführer","tags":["Nominativ","Singular"]},{"form":"Dschihadisten-Führer","tags":["alternative"]},{"form":"Dschihadistenführern","tags":["Dativ","Plural"]},{"form":"Dschihadistenführers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Führer einer Dschihadistengruppe"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus dem Substantiv Dschihadist, dem Fugenelement -en und dem Substantiv Führer"],"examples":[{"text":"„Algerien meldet Tötung von Dschihadistenführer“","reference":"Algerien meldet Tötung von Dschihadistenführer. ZEIT, 23. Dezember 2014, archiviert vom Original am 23. Dezember 2014 abgerufen am 18. Februar 2015 (HTML, Deutsch)."},{"text":"„Algeriens Armee tötet Dschihadistenführer: Abdelmalek Gouri, ein Führer der Islamisten-Gruppe al-Khilafa, ist offenbar bei einem Einsatz der algerischen Armee getötet worden. Die Leiche sei bereits identifiziert, erklärte ein Sprecher am Dienstag.“","reference":"Algerien meldet Tötung von Dschihadistenführer. Handelsblatt, 23. Dezember 2014, abgerufen am 15. Januar 2015 (HTML, Deutsch)."},{"text":"„Nie zuvor verfügte ein Dschihadistenführer über eine so große Anzahl von Kämpfern, ein so großes Einflussgebiet und scheinbar unerschöpfliche finanzielle Mittel.“","reference":"Terror-Krieg im Irak - Der Teufel vom Tigris. In: Bild.de. (URL, abgerufen am 15. Januar 2014) ."},{"text":"„Nach Angaben aus Sicherheitskreisen vom Freitag gab es erneut 109 Festnahmen – auch drei Dschihadistenführer seien aufgegriffen worden.“","reference":"Krawalle in Kairo - Mindestens ein Toter bei Muslimbrüder-Protest in Kairo. In: FOCUS Online. ISSN 0943-7576 (URL, abgerufen am 15. Januar 2014) ."},{"text":"„AQIM sei jedoch \"vom rechten Pfad\" abgewichen, begründete der Dschihadistenführer die Abspaltung und Gründung von \"Dschund al-Chilafa\".“","reference":"Algerische Terrorbrigaden: Frankreichs Albtraum. In: Spiegel Online. ISSN 0038-7452 (URL, abgerufen am 15. Januar 2014) ."},{"text":"„Mehrere wichtige Dschihadistenführer wie der Algerier Mokhtar Belmokhtar hätten im Süden Libyens Zuflucht gefunden.“","reference":"Le Drian gegen Militärintervention im Süden Libyens. In: Welt Online. ISSN 0173-8437 (URL, abgerufen am 15. Januar 2014) ."},{"text":"„Die irakische Regierung hatte zuvor geprüft, ob der Dschihadistenführer Abu Bakr al-Bagdadi bei einem Luftangriff getötet worden war.“","reference":"IS-Chef Al-Bagdadi offenbar bei Luftangriff verletzt. In: Zeit Online. ISSN 0044-2070 (URL, abgerufen am 15. Januar 2014) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschihadistenführer","id":"516c7caedaca3e"},"0064-0073:69993aa8a53c66":{"word":"DSB","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"DSB","de-DE":"DSB"},"forms":[],"senses":[{"definition":"Datenschutzbeauftragter"},{"definition":"Deutscher Sängerbund"},{"definition":"Deutscher Schachbund"},{"definition":"Deutscher Schützenbund"},{"definition":"Deutscher Schwerhörigenbund"},{"definition":"Deutscher Sportbund"},{"definition":"FC Deutsche Sportbrüder"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"DSB","id":"69993aa8a53c66"},"0064-0073:88eedcc40396ef":{"word":"DSGVO","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"DSGVO","de-DE":"DSGVO"},"forms":[{"form":"DS-GVO","tags":["alternative"]}],"senses":[{"definition":"Datenschutzgrundverordnung"}],"synonyms":["Datenschutz-Grundverordnung"],"origins":[],"examples":[{"text":"„Der Kunde ist verpflichtet, den Anbieter sorgfältig auszuwählen, Art. 28 Abs. 1 DSGVO.“","reference":"Wikipedia-Artikel „Software as a Service“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"DSGVO","id":"88eedcc40396ef"},"0064-0073:da9b005d569cc5":{"word":"Dschalalabad","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Dscha·lal·abad","de-DE":"Dscha·lal·abad"},"forms":[{"form":"Jalalabad","tags":["alternative"]},{"form":"Dschalalabads","tags":["Genitiv","Singular"]},{"form":"Dschellalabad","tags":["variant"]},{"form":"des Dschalalabad","tags":["Genitiv","Singular"]},{"form":"des Dschalalabads","tags":["Genitiv","Singular"]},{"form":"(das) Dschalalabad","tags":["Nominativ","Singular"]},{"form":"(dem) Dschalalabad","tags":["Dativ","Singular"]}],"senses":[{"definition":"Großstadt in Afghanistan"},{"definition":"Stadt in der zentralasiatischen Republik Kirgisistan"}],"synonyms":[],"origins":[],"examples":[{"text":"„Heute wundert es mich, dass die Verteidigung Dschalalabads so viel Staub aufgewirbelt hat.“","reference":"George MacDonald Fraser: Flashman in Afghanistan. Kübler, Lampertheim 2011, ISBN 978-3-94227-091-5, Seite 298 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschalalabad","id":"da9b005d569cc5"},"0064-0073:69e8610442d627":{"word":"DSM","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"DSM","de-DE":"DSM"},"forms":[],"senses":[{"definition":"Klassifikationssystem zur Definition und Diagnostik psychischer Erkrankungen"}],"synonyms":[],"origins":["Abkürzung für Diagnostic and Statistical Manual of Mental Disorders"],"examples":[{"text":"„Ein Vorzug von DSM ist die Standardisierung der einzelnen Merkmale, ein Vorteil von ICD ist die internationale Ausrichtung.“","reference":"Heinz Schlott/Rainer Tölle: Geschichte der Psychiatrie. Krankheitslehren, Irrwege, Behandlungsformen. C.H.Beck, München 2006, ISBN 3-406-53555-0, Seite 339"},{"text":"„Es kam so weit, dass die Sozialarbeiterin das DSM einfach auf den Fußboden warf und ich dann das Bild, das dabei zufällig aufschlug, eine Woche lang nachzustellen versuchte.“","reference":"Chuck Palahniuk: Flug 2039. Goldmann, München 2003, ISBN 978-3-442-54167-6, Seite 88 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"DSM","id":"69e8610442d627"},"0064-0073:33cbcc35e017f8":{"word":"DSN","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"DSN","de-DE":"DSN"},"forms":[],"senses":[{"definition":"Data Source Name"},{"definition":"Dataset-Name"},{"definition":"Deep Space Network"},{"definition":"Delivery Status Notification"},{"definition":"Deutsches Schwarzbuntes Niederungsrind"},{"definition":"Digitaler Service-Nachweis"},{"definition":"Direktion für Staatsschutz und Nachrichtendienst"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"DSN","id":"33cbcc35e017f8"},"0064-0073:b17a2f9ebd0070":{"word":"Dschungelstadt","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschun·gel·stadt","de-DE":"Dschun·gel·stadt"},"forms":[{"form":"Dschungelstadt","tags":["Nominativ","Singular"]},{"form":"Dschungelstädte","tags":["Nominativ","Plural"]},{"form":"Dschungelstädten","tags":["Dativ","Plural"]}],"senses":[{"definition":"in einem Dschungel gelegene Stadt"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Stadt"],"examples":[{"text":"„Die Wirklichkeit der Dschungelstadt, wie sie der alte Sir Wade beschrieben hatte, zweifelte Arthur Jermyn nun nicht mehr an, und als er Anfang 1912 dann tatsächlich auf ihre Überreste stieß, war er kaum überrascht.“","reference":"H.P. Lovecraft: Die Fakten über Arthur Jermyn und seine Familie. In: Das Gesamtwerk: Sämtliche Erzählungen und Zusammenarbeiten. Festa, Leipzig 2020, ISBN 978-3-865-52882-7, Seite 143 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelstadt","id":"b17a2f9ebd0070"},"0064-0073:7d59b7800c035d":{"word":"dschungelartig","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"dschun·gel·ar·tig","de-DE":"dschun·gel·ar·tig"},"forms":[{"form":"dschungelartig","tags":["Positiv"]},{"form":"dschungelartige","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"dschungelartigem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"dschungelartigen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"dschungelartiger","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"dschungelartiges","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist dschungelartig","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist dschungelartig","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist dschungelartig","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind dschungelartig","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"einem Dschungel ähnelnd, an einen Dschungel erinnernd"}],"synonyms":[],"origins":[],"examples":[{"text":"„Es war ein spektakulärer Schauplatz, ein kleiner bewaldeter Berg innerhalb der gewaltigen Kette der Westkordillere, eine wilde, dschungelartige Landschaft.“","reference":"Mark Bowden: Killing Pablo. Die Jagd auf Pablo Escobar, Kolumbiens Drogenbaron. 7. Auflage. Berlin Verlag, Berlin 2003, ISBN 978-3-833-30086-8, Seite 277 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"dschungelartig","id":"7d59b7800c035d"},"0064-0073:1de90fffb3ec72":{"word":"Dschidda","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Dsch·id·da","de-DE":"Dsch·id·da"},"forms":[{"form":"Dschiddas","tags":["Genitiv","Singular"]},{"form":"des Dschidda","tags":["Genitiv","Singular"]},{"form":"des Dschiddas","tags":["Genitiv","Singular"]},{"form":"(das) Dschidda","tags":["Nominativ","Singular"]},{"form":"(dem) Dschidda","tags":["Dativ","Singular"]}],"senses":[{"definition":"Hafenstadt in Saudi-Arabien"}],"synonyms":[],"origins":[],"examples":[{"text":"„Bei Dschidda, Beijing, Dubai oder London hätte sie sich nichts gedacht. Diese Städte waren übliche Stopps.“","reference":"Mohammed Hanif: Eine Kiste explodierender Mangos. A1 Verlag, München 2009, ISBN 978-3-940-66606-2, Seite 121 ."},{"text":"„Die Saudis verweigerten jegliche Verhandlung. Sie schickten bewaffnete Hubschrauber aus Dschidda, die das Deck des Tankers mit Maschinengewehren beharkten.“","reference":"Dalton Fury: Black Site. Festa, Leipzig 2015, ISBN 978-3-865-52359-4, Seite 7 ."},{"text":"„Im März und erneut in Mai organisierte die OIC indirekte Gespräche zwischen den Taliban und der NA in Dschidda, die ergebnislos endeten.“","reference":"Ahmed Rashid: Taliban. Afghanistans Gotteskämpfer und der neue Krieg am Hindukusch. C.H.Beck, München 2022, ISBN 978-3-406-78467-5, Seite 135 ."},{"text":"„Er spürte den Nahen Osten wie ein körperliches Gefühl auf seiner Haut: von der feuchten, dunstigen Luft Dschiddas am Roten Meer, wo einem im Hochsommer die Kleidung wie nasse Lappen am Körper klebte, bis zu den trockenen Wüstengebieten vor Kairo, wo die winterlichen Sandstürme den Staub in jede Pore trieben.“","reference":"David Ignatius: Operation Beirut. Rowohlt, Reinbek bei Hamburg 2011, ISBN 978-3-499-24910-5, Seite 66 ."},{"text":"„Sawakin war nicht für vieles bekannt, aber zumindest Muslime kannten die Stadt wegen ihres Hafens, in dem man auf die Fähre gelangte, die über das Rote Meer nach Dschidda fuhr.“","reference":"Mark Greaney: The Gray Man - Unter Beschuss. Festa, Leipzig 2017, ISBN 978-3-86552-544-4, Seite 269 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschidda","id":"1de90fffb3ec72"},"0064-0073:d6c16b203f7921":{"word":"Dschungellandschaft","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschun·gel·land·schaft","de-DE":"Dschun·gel·land·schaft"},"forms":[{"form":"Dschungellandschaft","tags":["Nominativ","Singular"]},{"form":"Dschungellandschaften","tags":["Nominativ","Plural"]}],"senses":[{"definition":"von Dschungeln geprägte Landschaft"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Landschaft"],"examples":[{"text":"„Blitze zuckten, erleuchteten mit grellem Stroboskop-Glanz eine dicht wuchernde Dschungellandschaft.“","reference":"Jeffrey Thomas: Konglomerat. In: Geschichten aus dem Cthulhu-Mythos. Festa, Leipzig 2012, ISBN 978-3-865-52121-7, Seite 144 ."},{"text":"„Fitzroy nahm einen Schluck, hob sein Glas dann zum Balkon hinter seinem Rücken und wies damit auf die Dschungellandschaft am östlichen Meeresufer.“","reference":"Mark Greaney: The Gray Man - Tödliche Jagd. Festa, Leipzig 2022, ISBN 978-3-98676-004-5, Seite 569 ."},{"text":"„Die Hügelkuppen wurden von einer dichten, sattgrünen Dschungellandschaft überwuchert.“","reference":"Ben Coes: Auge um Auge. Festa, Leipzig 2017, ISBN 978-3-86552-520-8, Seite 537 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungellandschaft","id":"d6c16b203f7921"},"0064-0073:d408d009dc2dc3":{"word":"Dschungelpflanze","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschun·gel·pflan·ze","de-DE":"Dschun·gel·pflan·ze"},"forms":[{"form":"Dschungelpflanze","tags":["Nominativ","Singular"]},{"form":"Dschungelpflanzen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Pflanze, die im Dschungel vorkommt"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Pflanze"],"examples":[{"text":"„Auf ihr waren Pflanzen und Tiere abgebildet, Vögel, wie ich auf den zweiten Blick erkannte, bunte Paradiesvögel und Dschungelpflanzen.“","reference":"Elisabeth Beer: Die Bücherjägerin. Roman. 1. Auflage. DuMont, Köln 2023, ISBN 978-3-8321- 6638-0 , Seite 160."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelpflanze","id":"d408d009dc2dc3"},"0064-0073:def2adf0a92244":{"word":"dschungelbedeckt","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"dschun·gel·be·deckt","de-DE":"dschun·gel·be·deckt"},"forms":[{"form":"dschungelbedeckt","tags":["Positiv"]},{"form":"dschungelbedeckte","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"dschungelbedecktem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"dschungelbedeckten","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"dschungelbedeckter","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"dschungelbedecktes","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist dschungelbedeckt","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist dschungelbedeckt","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist dschungelbedeckt","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind dschungelbedeckt","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"vom Dschungel bedeckt, Dschungelpflanzen als Bewuchs aufweisend"}],"synonyms":[],"origins":[],"examples":[{"text":"„Zweimal umrundete er die kleine Insel und betrachtete sich im Mondschein die dschungelbedeckten Hügel.“","reference":"Ben Coes: Power Down. Festa, Leipzig 2013, ISBN 978-3-865-52236-8, Seite 595 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"dschungelbedeckt","id":"def2adf0a92244"},"0064-0073:9de53bde93346f":{"word":"Dschirga","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschir·ga","de-DE":"Dschir·ga"},"forms":[{"form":"Dschirga","tags":["Nominativ","Singular"]},{"form":"Dschirgas","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Ratsversammlung von Stammesvertretern bei den Paschtunen"}],"synonyms":[],"origins":[],"examples":[{"text":"„Das Schura-Modell basiert zudem stark auf der Dschirga der Paschtunen, einem Rat, an dem alle Clan-Chefs teilnehmen, um über wichtige Anliegen des Stammes zu entscheiden.“","reference":"Ahmed Rashid: Taliban. Afghanistans Gotteskämpfer und der neue Krieg am Hindukusch. C.H.Beck, München 2022, ISBN 978-3-406-78467-5, Seite 158 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschirga","id":"9de53bde93346f"},"0064-0073:e542e373c4fbb1":{"word":"Dschandschawid","partOfSpeech":"Substantiv","gender":"","hyphenation":{"de-CH":"Dschand·scha·wid","de-DE":"Dschand·scha·wid"},"forms":[{"form":"Dschandschawid","tags":["Nominativ","Plural"]}],"senses":[{"definition":"bewaffnete Miliz in der Region Darfur im westlichen Sudan"}],"synonyms":[],"origins":[],"examples":[{"text":"„Natürlich kam es zu gelegentlichen Überfällen und Tötungen durch die Dschandschawid, sogar durch die örtlichen Rebellen, doch nur zu einem Bruchteil dessen, was andere Organisationen in der Region erlebten, wenn sie es wagten, sich im ›Lande der Fur‹ niederzulassen.“","reference":"Mark Greaney: The Gray Man - Unter Beschuss. Festa, Leipzig 2017, ISBN 978-3-86552-544-4, Seite 188 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschandschawid","id":"e542e373c4fbb1"},"0064-0073:4310ea5c8ee416":{"word":"Dschulis","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Dschu·lis","de-DE":"Dschu·lis"},"forms":[{"form":"Dschulis’","tags":["Genitiv","Singular"]},{"form":"des Dschulis","tags":["Genitiv","Singular"]},{"form":"(das) Dschulis","tags":["Nominativ","Singular"]},{"form":"(dem) Dschulis","tags":["Dativ","Singular"]}],"senses":[{"definition":"Dorf in Nordisrael"}],"synonyms":[],"origins":[],"examples":[{"text":"„Wenige Stunden nach dem Abschied von seiner Frau Gila und ihrem Sohn Jariv zu Hause in Rischon le-Zion traf er auf dem Stützpunkt für beschlagnahmte Fahrzeuge im Süden des Landes ein, irgendwo zwischen Nizanim und Dschulis.“","reference":"Tom Segev: 1967. Israels zweite Geburt. Siedler, München 2007, ISBN 978-3-886-80767-3, Seite 277 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschulis","id":"4310ea5c8ee416"},"0064-0073:7e17b20738d80f":{"word":"Dschungeldickicht","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Dschun·gel·di·ckicht","de-DE":"Dschun·gel·di·ckicht"},"forms":[{"form":"Dschungeldickicht","tags":["Nominativ","Singular"]},{"form":"Dschungeldickichte","tags":["Nominativ","Plural"]},{"form":"Dschungeldickichts","tags":["Genitiv","Singular"]},{"form":"Dschungeldickichten","tags":["Dativ","Plural"]},{"form":"Dschungeldickichtes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Dickicht, das in einem Dschungel liegt, Teil eines Dschungels ist"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Dickicht"],"examples":[{"text":"„Also hatte er es zerlegt und die Teile ins Dschungeldickicht geworfen.“","reference":"Mark Greaney: The Gray Man - Tödliche Jagd. Festa, Leipzig 2022, ISBN 978-3-98676-004-5, Seite 356 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungeldickicht","id":"7e17b20738d80f"},"0064-0073:ba470296cbf876":{"word":"Dschabla","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Dsch·ab·la","de-DE":"Dsch·ab·la"},"forms":[{"form":"Dschablas","tags":["Genitiv","Singular"]},{"form":"des Dschabla","tags":["Genitiv","Singular"]},{"form":"des Dschablas","tags":["Genitiv","Singular"]},{"form":"(das) Dschabla","tags":["Nominativ","Singular"]},{"form":"(dem) Dschabla","tags":["Dativ","Singular"]}],"senses":[{"definition":"syrische Küstenstadt im Gouvernement Latakia"}],"synonyms":[],"origins":[],"examples":[{"text":"„›Wir haben 'ne lange Fahrt vor uns, bis zu unserm Stützpunkt etwas östlich von Damaskus. 300 Klicks, und zwar keine Spazierfahrt, deshalb schließen wir uns einem Konvoi an, der oben in Dschabla losfährt, 'ne Viertelstunde von hier.‹“","reference":"Mark Greaney: The Gray Man - Undercover in Syrien. Festa, Leipzig 2024, ISBN 978-3-98676-132-5, Seite 255 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschabla","id":"ba470296cbf876"},"0064-0073:22aec45e882bfe":{"word":"Dschungelinsel","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschun·gel·in·sel","de-DE":"Dschun·gel·in·sel"},"forms":[{"form":"Dschungelinsel","tags":["Nominativ","Singular"]},{"form":"Dschungelinseln","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Insel, die von Dschungeln bedeckt ist, deren Landschaft aus Dschungeln besteht"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Insel"],"examples":[{"text":"„Der Planet hatte zwei Kontinente, einen größeren und einen kleineren, die einander gegenüberlagen und jeweils über den Äquator reichten, warme, tiefblaue Ozeane, ein Gewirr an Dschungelinseln, eine Atmosphäre, die reich an Sauerstoff und kohlendioxidgesättigt war, und eine Biosphäre, die man einfach nur als durchgeknallt bezeichnen kann.“","reference":"Edward Ashton: Mickey 7. Heyne, München 2022, ISBN 978-3-453-32172-4, Seite 274 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelinsel","id":"22aec45e882bfe"},"0064-0073:5e1bb77f4c12d3":{"word":"Dschungelgebiet","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Dschun·gel·ge·biet","de-DE":"Dschun·gel·ge·biet"},"forms":[{"form":"Dschungelgebiet","tags":["Nominativ","Singular"]},{"form":"Dschungelgebiete","tags":["Nominativ","Plural"]},{"form":"Dschungelgebiets","tags":["Genitiv","Singular"]},{"form":"Dschungelgebieten","tags":["Dativ","Plural"]},{"form":"Dschungelgebietes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Gebiet, das von Dschungel bedeckt ist"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Gebiet"],"examples":[{"text":"„Sie waren über die südlichen Dschungelgebiete hinweggeflogen, während unter ihnen wildschäumende Gewässer flossen.“","reference":"Frank Herbert: Der Wüstenplanet. Heyne, München 2001, ISBN 978-3-453-18683-5, Seite 370 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelgebiet","id":"5e1bb77f4c12d3"},"0064-0073:46cc242e1d0f75":{"word":"Dschungelgestrüpp","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Dschun·gel·ge·strüpp","de-DE":"Dschun·gel·ge·strüpp"},"forms":[{"form":"Dschungelgestrüpp","tags":["Nominativ","Singular"]},{"form":"Dschungelgestrüppe","tags":["Nominativ","Plural"]},{"form":"Dschungelgestrüpps","tags":["Genitiv","Singular"]},{"form":"Dschungelgestrüppen","tags":["Dativ","Plural"]},{"form":"Dschungelgestrüppes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Gestrüpp in einem Dschungel"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Gestrüpp"],"examples":[{"text":"„Immer drückender wurde die Hitze zwischen den beengten, erstickenden Mauern aus Urwaldgehölz und Dschungelgestrüpp.“","reference":"Clark Ashton Smith: Die Knospen des Grabes. In: Die Grabgewölbe von Yoh-Vombis. Festa, Leipzig 2012, ISBN 978-3-865-52089-0, Seite 238 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelgestrüpp","id":"46cc242e1d0f75"},"0064-0073:74bd34b112b019":{"word":"Dschabal Katrina","partOfSpeech":"Toponym","gender":"der","hyphenation":{"de-CH":"Dscha·bal Kat·ri·na","de-DE":"Dscha·bal Kat·ri·na"},"forms":[{"form":"Jabal Katrina","tags":["alternative"]},{"form":"Dschabal Katrina","tags":["Nominativ","Singular"]},{"form":"Dschabal Katrinas","tags":["Genitiv","Singular"]}],"senses":[{"definition":"höchster Berg in Ägypten"}],"synonyms":[],"origins":[],"examples":[{"text":"Der Dschabal Katrina liegt auf der Halbinsel Sinai.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschabal Katrina","id":"74bd34b112b019"},"0064-0073:fe81c124251ce2":{"word":"Dschungelbewohner","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschun·gel·be·woh·ner","de-DE":"Dschun·gel·be·woh·ner"},"forms":[{"form":"Dschungelbewohner","tags":["Nominativ","Singular"]},{"form":"Dschungelbewohnern","tags":["Dativ","Plural"]},{"form":"Dschungelbewohners","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Bewohner von Dschungelregionen"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Bewohner"],"examples":[{"text":"„Sie stammten von Dschungelbewohnern ab, die in den tiefen, widerlich strotzenden Urwäldern der Venus unter primitivsten Bedingungen einen ewigen Überlebenskampf gegen furchterregende Tiere und Insekten ausfochten, nicht selten auch untereinander.“","reference":"Clark Ashton Smith: Ein Abenteuer in der Zukunft. In: Das Labyrinth des Maal Dweb. Festa, Leipzig 2013, ISBN 978-3-86552-128-6, Seite 74 ."},{"text":"„Sie wiesen bereits die Eigenschaften von Dschungelbewohnern auf, obwohl sie erst seit ein paar Generationen in dieser Umgebung leben konnten.“","reference":"Robert E. Howard: Das Tal des Wurmes. In: Der schwarze Hund des Todes. Festa, Leipzig 2013, ISBN 978-3-86552-131-6, Seite 237 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelbewohner","id":"fe81c124251ce2"},"0064-0073:dad06509ffdc89":{"word":"Dschungelkrankheit","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschun·gel·krank·heit","de-DE":"Dschun·gel·krank·heit"},"forms":[{"form":"Dschungelkrankheit","tags":["Nominativ","Singular"]},{"form":"Dschungelkrankheiten","tags":["Nominativ","Plural"]}],"senses":[{"definition":"in Dschungeln verbreitete Krankheit"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Krankheit"],"examples":[{"text":"„In der Tat dachte ich mir oft, dass die einfachste Erklärung für die Veränderung in Marsden lautete: Eine tödliche Dschungelkrankheit, von der er sich noch nicht zur Gänze wieder erholt hatte, trieb ihn um.“","reference":"Clark Ashton Smith: Die Venus von Azombeii. In: Das Labyrinth des Maal Dweb. Festa, Leipzig 2013, ISBN 978-3-86552-128-6, Seite 106 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelkrankheit","id":"dad06509ffdc89"},"0064-0073:c22d157866cdc9":{"word":"Dschungelkrieg","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dschun·gel·krieg","de-DE":"Dschun·gel·krieg"},"forms":[{"form":"Dschungelkrieg","tags":["Nominativ","Singular"]},{"form":"Dschungelkriege","tags":["Nominativ","Plural"]},{"form":"Dschungelkriegs","tags":["Genitiv","Singular"]},{"form":"Dschungelkriegen","tags":["Dativ","Plural"]},{"form":"Dschungelkrieges","tags":["Genitiv","Singular"]}],"senses":[{"definition":"bewaffneter Konflikt, der im Dschungel ausgetragen wird"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Dschungel und Krieg"],"examples":[{"text":"„Die Fans des Serienmeisters APR FC kleiden sich zudem in Fantasieuniformen und führen Tänze auf, die an den Dschungelkrieg erinnern.“","reference":"Tom Mustroph: Fußball 30 Jahre nach dem Genozid in Ruanda. Zwischen Voodoo und Aufbruch. In: Der Tagesspiegel Online. 2024-04-07 (URL, abgerufen am 5. Februar 2026) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelkrieg","id":"c22d157866cdc9"},"0064-0073:b77b43424c99ac":{"word":"Dschungelkatze","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschun·gel·kat·ze","de-DE":"Dschun·gel·kat·ze"},"forms":[{"form":"Dschungelkatze","tags":["Nominativ","Singular"]},{"form":"Dschungelkatzen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"in Dschungeln lebende Wildkatze"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Katze"],"examples":[{"text":"„Kelka war klein, kräftig gebaut und tödlich wie eine Dschungelkatze.“","reference":"Robert E. Howard: Die Kämpfer von Walhalla. In: Der schwarze Hund des Todes. Festa, Leipzig 2013, ISBN 978-3-86552-131-6, Seite 62 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelkatze","id":"b77b43424c99ac"},"0064-0073:6539b96fd3ed7f":{"word":"Dschemdet-Nasr-Zeit","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dsc·hem·det-Nasr-Zeit","de-DE":"Dsc·hem·det-Nasr-Zeit"},"forms":[{"form":"Dschemdet-Nasr-Zeit","tags":["Nominativ","Singular"]}],"senses":[{"definition":"prähistorische, kulturelle Entwicklungsstufe Mesopotamiens"}],"synonyms":[],"origins":[],"examples":[{"text":"„Undeutlich bleiben die Übergänge von der Späturuk-Zeit (3500–3300) zu jener Periode, die nach einem namensgebenden Fundort in Zentralmesopotamien auch als Dschemdet-Nasr-Zeit (3300–3000) bezeichnet wird.“","reference":"Gebhard J. Selz: Sumerer und Akkader. Geschichte, Gesellschaft, Kultur. C.H.Beck, München 2022, ISBN 978-3-406-78427-9, Seite 16 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschemdet-Nasr-Zeit","id":"6539b96fd3ed7f"},"0064-0073:a05a36bfc8f74b":{"word":"Dschemdet Nasr","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Dsc·hem·det Nasr","de-DE":"Dsc·hem·det Nasr"},"forms":[{"form":"Dschemdet Nasrs","tags":["Genitiv","Singular"]},{"form":"des Dschemdet Nasr","tags":["Genitiv","Singular"]},{"form":"des Dschemdet Nasrs","tags":["Genitiv","Singular"]},{"form":"(das) Dschemdet Nasr","tags":["Nominativ","Singular"]},{"form":"(dem) Dschemdet Nasr","tags":["Dativ","Singular"]}],"senses":[{"definition":"archäologischer Fundplatz im Irak"}],"synonyms":[],"origins":[],"examples":[{"text":"„Am Fundort Dschemdet Nasr nahe der nordbabylonischen Stadt Kisch, der dieser Periode den Namen gab, fand sich ein sogenannter Palast.“","reference":"Gebhard J. Selz: Sumerer und Akkader. Geschichte, Gesellschaft, Kultur. C.H.Beck, München 2022, ISBN 978-3-406-78427-9, Seite 42 ."}],"idioms":[],"collocations":[],"derivations":["Dschemdet-Nasr-Zeit"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschemdet Nasr","id":"a05a36bfc8f74b"},"0064-0073:9c493ddb3201aa":{"word":"Dschungelregion","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dschun·gel·re·gi·on","de-DE":"Dschun·gel·re·gi·on"},"forms":[{"form":"Dschungelregion","tags":["Nominativ","Singular"]},{"form":"Dschungelregionen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"von Dschungeln geprägte Region"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Dschungel und Region"],"examples":[{"text":"„Als wir die Dschungelregion betraten, dröhnten die Trommeln über das geheimnisvolle Tal, das zwischen den rohen Hügeln eingebettet lag.“","reference":"Robert E. Howard: Das Tal des Wurmes. In: Der schwarze Hund des Todes. Festa, Leipzig 2013, ISBN 978-3-86552-131-6, Seite 239 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dschungelregion","id":"9c493ddb3201aa"}};
